import{_ as t,o as a,c as r,a3 as s}from"./chunks/framework.DhF4LrUq.js";const o="/shipperdog/snapshot/screenshots/roles/console-sec-approvals.png",g=JSON.parse('{"title":"Security / Compliance Reviewer quickstart","description":"Quickstart for Security and Compliance Reviewers — the security approval step, scan-gate evidence, restricted security reports, and the audit trail.","frontmatter":{"description":"Quickstart for Security and Compliance Reviewers — the security approval step, scan-gate evidence, restricted security reports, and the audit trail."},"headers":[],"relativePath":"roles/security-reviewer.md","filePath":"roles/security-reviewer.md"}'),i={name:"roles/security-reviewer.md"};function n(h,e,l,c,d,p){return a(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="security-compliance-reviewer-quickstart" tabindex="-1">Security / Compliance Reviewer quickstart <a class="header-anchor" href="#security-compliance-reviewer-quickstart" aria-label="Permalink to &quot;Security / Compliance Reviewer quickstart&quot;">​</a></h1><h2 id="who-you-are" tabindex="-1">Who you are <a class="header-anchor" href="#who-you-are" aria-label="Permalink to &quot;Who you are&quot;">​</a></h2><p>You are the control the release pipeline answers to before it widens. ShipperDog models this as two system roles on one page because the workflow is one: <strong><code>SECURITY_REVIEWER</code></strong> signs the Security step of each release&#39;s approval chain, <strong><code>COMPLIANCE_REVIEWER</code></strong> signs the Compliance step (with conditional approvals where regulated features changed). Your surface is the Console. You review gate evidence — SAST, dependency scans, mobile security scans — read every standing rule the pipeline runs, watch the audit trail, and you are one of the two organization roles (with the Organization Admin) who can even see reports testers filed as security issues — beyond the platform administrator&#39;s audited override.</p><h2 id="what-you-can-do" tabindex="-1">What you can do <a class="header-anchor" href="#what-you-can-do" aria-label="Permalink to &quot;What you can do&quot;">​</a></h2><ul><li><strong>Approve or block on your step.</strong> The Security (or Compliance) signature in the approval chain is exclusively yours — no other role can give it, and without it the release does not move.</li><li><strong>Review gate evidence.</strong> Quality gates that run security-class scans publish their evidence, observed values, and thresholds on the release dashboard; overrides of a failed gate are recorded decisions you can audit after the fact.</li><li><strong>See the restricted reports.</strong> Feedback filed as a security issue is invisible to the general queue — visible only to your role and the Organization Admin, and triaged by the same narrow circle.</li><li><strong>Read the rules, author none.</strong> Read-only visibility into environments, approval workflows, gate definitions, rings, release policies, and ABAC attribute policies: if you need a rule changed, that is a governance decision for the <a href="/shipperdog/snapshot/roles/org-admin">Organization Admin</a> — but every rule and its evaluation history are open to you.</li><li><strong>Watch the trail.</strong> The audit trail is immutable; the SIEM stream that exports it off-platform is configured by your Organization Admin — the delivery log and security-event notifications are yours to watch.</li></ul><h2 id="first-15-minutes" tabindex="-1">First 15 minutes <a class="header-anchor" href="#first-15-minutes" aria-label="Permalink to &quot;First 15 minutes&quot;">​</a></h2><p>The screenshots come from the locally running development stack with its seeded demo world — what you see here is what you will see there.</p><ol><li><p><strong>Sign in and read the dashboard.</strong> The pending-actions panel personalizes to your role: the Security (or Compliance) steps waiting on your signature, each deep-linking to its release.</p></li><li><p><strong>Open the release waiting on you.</strong> The release dashboard&#39;s <strong>Approvals</strong> panel shows the live round — who has signed, who is outstanding — with the approve and reject affordances sitting on the steps the round is currently waiting on (the platform enforces whose signature each step accepts):</p><p><img src="'+o+'" alt="The release approvals as the Security Reviewer"></p></li><li><p><strong>Check the evidence before you sign.</strong> On the <strong>Quality Gates</strong> panel, open the security-class gates: their state, the evidence links behind them, observed values against thresholds. A gate with no data says so honestly — <code>NO_DATA</code> is a refusal, not a pass; read <a href="/shipperdog/snapshot/concepts/approvals-gates">approvals and gates</a> for how the pipeline treats it.</p></li><li><p><strong>Check the restricted queue.</strong> Reports testers filed as security issues appear in the release&#39;s feedback section for you (and your Organization Admin) alone — everyone else sees nothing, not even the existence of the row. Triage severity on that queue with the <a href="/shipperdog/snapshot/roles/qa-engineer">QA Engineer</a>&#39;s discipline: it is the same surface, narrower visibility.</p></li><li><p><strong>Skim the standing rules.</strong> Release policies and ABAC policies shape what can promote where — read them once so a refusal later is never a surprise: <a href="/shipperdog/snapshot/concepts/authorization">authorization</a> covers the decision chain; <a href="/shipperdog/snapshot/concepts/security-model">the security model</a> covers signed URLs, tenancy, and the audit posture.</p></li></ol><h2 id="where-to-go-next" tabindex="-1">Where to go next <a class="header-anchor" href="#where-to-go-next" aria-label="Permalink to &quot;Where to go next&quot;">​</a></h2><p>Hand-off task list:</p><ul><li>[ ] Read <a href="/shipperdog/snapshot/concepts/security-model">the security model</a> first</li><li>[ ] Read <a href="/shipperdog/snapshot/concepts/approvals-gates">approvals and gates</a> for the chain you gate and the override records you audit</li><li>[ ] Read <a href="/shipperdog/snapshot/concepts/authorization">authorization</a> for the decision chain your reviews ride on</li><li>[ ] How-tos as they land: <a href="/shipperdog/snapshot/how-to/console/audit-log">audit log</a>, <a href="/shipperdog/snapshot/how-to/console/siem-streams">SIEM streams</a> (configured by your Organization Admin)</li></ul>',11)])])}const y=t(i,[["render",n]]);export{g as __pageData,y as default};
